import getpass
import subprocess
import sys
_gsp = subprocess.run(["git", "--no-optional-locks", "status", "--porcelain=v2", "--branch"], capture_output=True, text=True)
if _gsp.returncode != 0:
    sys.stderr.write(_gsp.stderr or "")
    raise SystemExit(_gsp.returncode)
_gs = _gsp.stdout.splitlines()
_branch = _head = None
_status_lines = []
for _l in _gs:
    if _l.startswith("# branch.head "):
        _branch = _l.split(" ", 2)[2]
    elif _l.startswith("# branch.oid "):
        _head = _l.split(" ", 2)[2]
